from pathlib import Path
import re
root=Path(__file__).resolve().parent.parent
html=(root/'index.html').read_text();start=html.index('<svg aria-label="Tesla');svg=html[start:html.index('</svg></div><div class="charge-status">',start)+6]
# The car includes an inner SVG; keep the outermost scene through the known closing marker.
svg=svg.replace('viewbox=', 'viewBox=').replace('./assets/','../assets/');svg=svg.replace('class="section-cut" x="450" y="-150" width="300" height="850" fill="url(#section-right-fade)"','class="section-cut" x="450" y="-150" width="300" height="850" fill="black"')
svg=re.sub(r'<rect class="section-cut"[^>]+/>','<circle class="lens-cut" cx="430" cy="226" r="120" fill="black"/>',svg)
svg=re.sub(r'<rect class="section-window"[^>]+/>','<circle class="lens-window" cx="430" cy="226" r="120"/>',svg)
svg=svg.replace('class="tesla-layer"','class="tesla-layer scanning"').replace('fill="url(#mechanics-right-fade)"','fill="white"')
svg=re.sub(r'<g class="section-indicator".*?</g>', '<g class="lens-ring" pointer-events="none"><circle cx="430" cy="226" r="120" fill="none" stroke="currentColor" stroke-width="1.4"/><circle cx="430" cy="226" r="125" fill="none" stroke="currentColor" stroke-width=".7" opacity=".4"/></g>',svg,flags=re.S)
svg=re.sub(r'<g class="energy-plane">.*?</g></g>', '',svg,flags=re.S) if False else svg
# Replace the complete energy-plane group using the following known roadside group boundary.
a=svg.index('<g class="energy-plane">');b=svg.index('<g aria-hidden="true">',a)
paths=['M80 460C240 460 300 430 440 430H990Q1032 430 1032 385V365','M160 506H590Q630 506 650 475L690 450H1010Q1032 450 1032 385V365','M410 550L460 510H870Q1032 510 1032 385V365']
variants=[('N1','Энергетическая линза','Чёткий круг раскрывает механику. Бирюзовые силовые кабели с белым сердечником.','#73f5e8'),('N2','Мягкий рентген','Круг с плавной границей. Двойная холодная трасса: голубой + фиолетовый.','#a5b4ff'),('N3','Инженерная оптика','Тонкая измерительная шкала вокруг круга. Кабели в раскрытом подземном канале.','#9ad9ff'),('N4','Импульс сети','Круг и концентрические кольца. Световые импульсы расходятся по разветвлённой сети.','#87ffdb')]
cards=[]
for i,(code,name,desc,color) in enumerate(variants):
 wire='<g class="energy-plane"><path d="M80 412L1070 412 1160 550H15Z" fill="#142335" opacity=".85"/>'
 if i==2:wire+='<path d="M50 460H500L680 493H1032V360" fill="none" stroke="#080e17" stroke-width="38"/><path d="M50 460H500L680 493H1032V360" fill="none" stroke="#68839b" stroke-width="42" opacity=".22"/>'
 for j,path in enumerate(paths):
  hue=('#9ba0ff' if i==1 and j==1 else color)
  wire+=f'<path d="{path}" fill="none" stroke="#08121d" stroke-width="12" stroke-linecap="round"/><path d="{path}" fill="none" stroke="{hue}" stroke-width="7" opacity=".45" filter="url(#glow)"/><path d="{path}" fill="none" stroke="{hue}" stroke-width="3"/><path class="pulse" d="{path}" fill="none" stroke="#ebffff" stroke-width="1.4" stroke-dasharray="22 95"/>'
 wire+='</g>'
 scene=svg[:a]+wire+svg[b:];scene=scene.replace('<defs>','<defs><filter id="glow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="5"/></filter>',1)
 
 if i==1:
  scene=scene.replace('<defs>', '<defs><radialGradient id="lens-soft"><stop offset="0.75" stop-color="black"/><stop offset="1" stop-color="white"/></radialGradient>',1).replace('r="120" fill="black"','r="120" fill="url(#lens-soft)"')
 if i==3:
  scene=scene.replace('</g><g aria-hidden="true">','<g fill="#c3fff0">'+''.join(f'<circle cx="{x}" cy="{y}" r="4"/>' for x,y in [(440,430),(690,450),(870,510),(1032,385)])+'</g></g><g aria-hidden="true">',1)
 scene=scene.replace('class="tesla-layer scanning"',f'class="tesla-layer scanning v{i}"');scene=re.sub(r'\bid="([^"]+)"',lambda m:f'id="{code}-{m[1]}"',scene);scene=re.sub(r'url\(#([^\)]+)\)',lambda m:f'url(#{code}-{m[1]})',scene)
 cards.append(f'<article data-variant="{code}" style="--accent:{color}"><header><b>{code}</b><h2>{name}</h2></header><div class="scene"><img class="city" src="../assets/moscow-city-night.jpg"/>{scene}</div><p>{desc}</p></article>')
page='''<!DOCTYPE html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../fonts/fonts.css"><title>Четыре варианта · Tesla и энергосеть</title><style>*{box-sizing:border-box}body{background:#101922;color:#e8f0f4;margin:0;padding:24px;font-family:Onest,sans-serif}h1{font-size:27px;font-weight:500;margin:0 0 8px}body>p{color:#90a7ba;font-size:12px;margin:0 0 20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}article{background:#182735;border:1px solid #334b60;border-radius:12px;overflow:hidden}header{display:flex;gap:15px;align-items:center;padding:15px 20px}header b{font-size:12px;color:var(--accent)}h2{font-size:19px;margin:0;font-weight:500}.scene{position:relative;aspect-ratio:1200/560;overflow:hidden}.city{position:absolute;width:100%;height:100%;object-fit:cover;filter:brightness(.47) saturate(.7)}svg[role=group]{position:relative;width:100%;height:100%;color:var(--accent)}article>p{font-size:12px;line-height:1.6;margin:0;padding:15px 20px;color:#b7cbd9;min-height:70px}.charging-wire-signal,.charging-wire{stroke-dashoffset:0}.charge-plug{display:none}.pulse{animation:flow 4s linear infinite}.section-indicator{display:none}.lens-ring{filter:drop-shadow(0 0 3px var(--accent))}.v1 .lens-ring{opacity:.55}.v2 .lens-ring{stroke-dasharray:2 7}.v3 .lens-ring{stroke-dasharray:8 5}.v3 .lens-ring circle:last-child{stroke-width:3;opacity:.35}svg image{pointer-events:none}[data-tesla-hit]{cursor:crosshair;outline:none}.lens-cut,.lens-window,.lens-ring{pointer-events:none}.v1 .tesla-section{filter:drop-shadow(0 0 8px #adceff88)}@keyframes flow{to{stroke-dashoffset:-234}}@media(max-width:700px){.grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}</style><h1>Круговое раскрытие Tesla × подземная энергосеть</h1><p>Четыре направления на реальных фотографиях. Проведите по автомобилю: круг перемещается по двум осям. Иллюстративная механика — не заводская CAD-модель.</p><div class="grid">'''+''.join(cards)+'''</div><script>for(const article of document.querySelectorAll('article')){const car=article.querySelector('.tesla-layer'),hit=article.querySelector('[data-tesla-hit]');hit.addEventListener('pointermove',e=>{const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(car.getScreenCTM().inverse());for(const c of article.querySelectorAll('.lens-cut,.lens-window,.lens-ring circle')){c.setAttribute('cx',p.x);c.setAttribute('cy',p.y)}});hit.setAttribute('aria-label','Круговое раскрытие Tesla');}</script></html>'''
(root/'design-options-v3').mkdir(exist_ok=True);(root/'design-options-v3/index.html').write_text(page)
